from passlib.context import CryptContext

pwd_context = CryptContext(schemes=['bcrypt'], deprecated='auto')

def sifre_hashle(sifre: str) -> str:
    return pwd_context.hash(sifre)

def sifre_dogrula(duz_sifre: str, hashli_sifre: str) -> bool:
    return pwd_context.verify(duz_sifre, hashli_sifre)

import jwt
from datetime import datetime, timedelta

SECRET_KEY = 'GIRESUN_UNIVERSITESI_GIZLI_ANAHTARI_123'
ALGORITHM = 'HS256'

def token_olustur(kullanici_adi: str):
    sure = datetime.utcnow() + timedelta(minutes=30)
    veri = {'sub': kullanici_adi, 'exp': sure}
    return jwt.encode(veri, SECRET_KEY, algorithm=ALGORITHM)

from fastapi import Depends, HTTPException
from fastapi.security import OAuth2PasswordRequestForm

@app.post('/token')
def giris_yap(form_data: OAuth2PasswordRequestForm = Depends()):
    # Örnek statik kontrol (veya veritabanından):
    if form_data.username == 'ali@mail.com' and form_data.password == '12345':
        bilet = token_olustur(form_data.username)
        return {'access_token': bilet, 'token_type': 'bearer'}
    raise HTTPException(status_code=400, detail='Hatalı e-posta veya parola!')

def aktif_kullanici(token: str = Depends(oauth2_scheme)):
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        kullanici = payload.get('sub')
        if kullanici is None:
            raise HTTPException(status_code=401, detail='Geçersiz Bilet!')
        return kullanici
    except:
        raise HTTPException(status_code=401, detail='Yetkisiz Giriş (401)!')

